const choice = $input.item.json.choices && $input.item.json.choices[0];
if (!choice || !choice.message || !choice.message.content) {
  throw new Error('OpenRouter did not return a usable completion: ' + JSON.stringify($input.item.json));
}
const requestBody = $('Idea Intake Webhook').item.json.body;
return { json: {
  refinedPrompt: choice.message.content.trim(),
  originalIdea: requestBody.idea,
  requestId: requestBody.requestId || (Date.now() + '-' + Math.random().toString(36).slice(2)),
  githubOwner: requestBody.githubOwner,
  githubRepo: requestBody.githubRepo,
  githubBranch: requestBody.githubBranch || 'main',
  assetSlug: (requestBody.idea || 'asset').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 40) || 'asset'
} };

const candidate = $input.item.json.candidates && $input.item.json.candidates[0];
const part = candidate && candidate.content && candidate.content.parts && candidate.content.parts.find(p => p.inlineData);
if (!part) {
  throw new Error('Gemini response did not contain image data: ' + JSON.stringify($input.item.json).slice(0, 500));
}
const b64 = part.inlineData.data;
const mime = part.inlineData.mimeType || 'image/png';
const buffer = Buffer.from(b64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'raw_asset.png', mime);
return { json: $input.item.json, binary: { data: binary } };

const binary = $input.item.binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const dataUri = 'data:' + binary.mimeType + ';base64,' + buffer.toString('base64');
return { json: { ...$('Extract Refined Prompt').item.json, imageDataUri: dataUri }, binary: $input.item.binary };

