        <Model />
      </Canvas>
    </View>
  );
}

const styles = StyleSheet.create({ container: { flex: 1 } });
`;

return { json: {
  ...ctx,
  componentCode,
  componentFileName: pascal + 'Viewer.tsx',
  componentPath: 'components/generated/' + pascal + 'Viewer.tsx',
  modelPath
}, binary: $input.item.binary };
